settings.css:
.pc {
  display: flex;
  flex-direction: column;
  gap: 16px;
  height: 100%;
  box-sizing: border-box;
  padding: 20px;
  font-family: 'Inter', 'Roboto', system-ui, sans-serif;
  color: #0f172a;
  background: #ffffff;
  border-radius: 16px;
  box-shadow: 0 4px 24px rgba(15, 23, 42, 0.06);
}

/* Header: title, min/max cards, view controls */
.pc__bar { display: flex; align-items: center; gap: 16px; flex-wrap: wrap; }
.pc__title { margin: 0; font-size: 18px; font-weight: 700; letter-spacing: -0.01em; }
.pc__kpis { display: flex; gap: 12px; }
.kpi {
  display: flex;
  flex-direction: column;
  gap: 4px;
  min-width: 84px;
  padding: 10px 16px;
  border-radius: 14px;
  background: linear-gradient(180deg, #f8fafc, #eef2f7);
  border: 1px solid #e6ebf2;
  box-shadow: inset 0 1px 0 #ffffff;
}
.kpi__label { font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.08em; color: #94a3b8; }
.kpi__value { font-size: 20px; font-weight: 800; line-height: 1; }

/* Controls */
.pc__controls { margin-left: auto; display: flex; align-items: center; gap: 12px; }
.pc__select-label { display: flex; align-items: center; gap: 8px; font-size: 12px; font-weight: 600; color: #64748b; }
.pc__select-label[hidden] { display: none; }
.pc__select {
  padding: 8px 12px;
  border: 1px solid #d8dee9;
  border-radius: 10px;
  background: #fff;
  font-size: 13px;
  color: #0f172a;
  cursor: pointer;
  transition: border-color 0.15s ease, box-shadow 0.15s ease;
}
.pc__select:hover { border-color: #2f6bff; }
.pc__select:focus { outline: none; border-color: #2f6bff; box-shadow: 0 0 0 3px rgba(47, 107, 255, 0.15); }
.pc__toggle {
  padding: 9px 18px;
  border: 0;
  border-radius: 10px;
  background: linear-gradient(180deg, #3b82f6, #2f6bff);
  color: #fff;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  box-shadow: 0 2px 8px rgba(47, 107, 255, 0.35);
  transition: transform 0.1s ease, box-shadow 0.15s ease;
}
.pc__toggle:hover { box-shadow: 0 4px 14px rgba(47, 107, 255, 0.45); }
.pc__toggle:active { transform: translateY(1px); }

/* Views fill the remaining space */
.pc__view { flex-grow: 1; min-height: 0; }
.pc__view[hidden] { display: none; }
.pc__table-wrap { overflow: auto; border: 1px solid #eef1f6; border-radius: 14px; }

/* Telemetry table */
.pc__table { width: 100%; border-collapse: collapse; font-size: 13px; }
.pc__table th {
  position: sticky;
  top: 0;
  background: #f8fafc;
  text-align: left;
  padding: 12px 16px;
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: #94a3b8;
  border-bottom: 1px solid #e6ebf2;
}
.pc__table td { padding: 12px 16px; border-bottom: 1px solid #f1f5f9; color: #334155; }
.pc__table tbody tr:last-child td { border-bottom: 0; }
.pc__table tbody tr:hover { background: #f8fafc; }

settings.js:
// Plain HTML mode: render an ECharts heatmap into the container and feed it from
// a custom subscription. ECharts is loaded from a CDN via the Resources tab.
// Access CDN globals through window. so the editor's linter doesn't flag them.
const echarts = window.echarts;
const el = container.querySelector('#heatmap');
const chart = echarts.init(el);

const fmt = (ts) => new Date(ts).toLocaleString();

// Header / view elements (Plain HTML — query the DOM and update it directly).
const minEl = container.querySelector('#pcMin');
const maxEl = container.querySelector('#pcMax');
const rowsEl = container.querySelector('#pcRows');
const heatmapEl = container.querySelector('#heatmap');
const tableEl = container.querySelector('#table');
const toggleBtn = container.querySelector('#pcToggle');
const deviceSel = container.querySelector('#pcDevice');
const deviceLabel = container.querySelector('#pcDeviceLabel');

let allRows = []; // every telemetry point, for the table
let selectedDevice = null; // device shown in the table

chart.setOption({
  tooltip: {
    position: 'top',
    formatter: (p) => fmt(p.data.ts) + '<br/>' + p.data.device + ': <b>' + p.data.value[2] + '</b>',
  },
  grid: { left: 8, right: 24, top: 16, bottom: 12, containLabel: true }, // reserve room for axis labels
  xAxis: { type: 'category', data: [], splitArea: { show: true }, axisLabel: { rotate: 45 } }, // timestamps
  yAxis: { type: 'category', data: [], splitArea: { show: true } }, // device names
  visualMap: {
    show: false, // colour mapping only — no legend
    min: 0,
    max: 1,
    inRange: { color: ['#fdd835', '#fb8c00', '#e53935'] }, // yellow → orange → red
  },
  series: [{ type: 'heatmap', data: [], emphasis: { itemStyle: { shadowBlur: 8 } } }],
});

// Keep the chart sized to the widget area.
const resizeObserver = new window.ResizeObserver(() => chart.resize());
resizeObserver.observe(el);

// Switch between the heatmap and a full telemetry table.
let showTable = false;
toggleBtn.addEventListener('click', () => {
  showTable = !showTable;
  heatmapEl.hidden = showTable;
  tableEl.hidden = !showTable;
  deviceLabel.hidden = !showTable; // the device picker only matters for the table
  toggleBtn.textContent = showTable ? 'Show heatmap' : 'Show table';
  if (!showTable) chart.resize();
});

// Filter the table to the selected device.
function renderTable() {
  const filtered = allRows.filter((r) => r.device === selectedDevice).sort((a, b) => b.ts - a.ts);
  rowsEl.innerHTML = filtered.map((r) => `<tr><td>${fmt(r.ts)}</td><td>${r.value}</td></tr>`).join('');
}
deviceSel.addEventListener('change', () => {
  selectedDevice = deviceSel.value;
  renderTable();
});

// Build the heatmap from one series per device: x = timestamp, y = device name.
// Each data entry carries its datasource (entityName) and its [ts, value] points.
function render(entries) {
  const devices = entries.map((e) => e.datasource.entityName);

  // Union of all timestamps across devices, sorted ascending → x axis.
  const seen = {};
  entries.forEach((e) => e.data.forEach(([ts]) => (seen[ts] = true)));
  const times = Object.keys(seen)
    .map(Number)
    .sort((a, b) => a - b);
  const xIndex = {};
  times.forEach((ts, i) => (xIndex[ts] = i));

  const cells = [];
  const rows = [];
  let min = Infinity;
  let max = -Infinity;
  entries.forEach((entry, y) => {
    entry.data.forEach(([ts, value]) => {
      const v = Number(value);
      if (v < min) min = v;
      if (v > max) max = v;
      cells.push({ value: [xIndex[ts], y, v], ts: Number(ts), device: entry.datasource.entityName });
      rows.push({ device: entry.datasource.entityName, ts: Number(ts), value: v });
    });
  });
  if (!cells.length) {
    min = 0;
    max = 1;
  }

  // Min / max cards.
  minEl.textContent = rows.length ? min : '—';
  maxEl.textContent = rows.length ? max : '—';

  // Heatmap.
  chart.setOption({
    xAxis: { data: times.map(fmt) },
    yAxis: { data: devices },
    visualMap: { min, max }, // colour auto-scales yellow → red between the data's min and max
    series: [{ data: cells }],
  });

  // Populate the device picker (keeping the current choice) and fill the table.
  allRows = rows;
  if (selectedDevice === null || !devices.includes(selectedDevice)) {
    selectedDevice = devices[0] || null;
  }
  deviceSel.innerHTML = devices
    .map((d) => `<option${d === selectedDevice ? ' selected' : ''}>${d}</option>`)
    .join('');
  renderTable();
}

// Subscribe to "peopleCount" over the dashboard time window for every device of
// type "peopleCount" — inline entity filter, no alias. More devices → more rows.
const subOpts = {
  type: 'timeseries',
  useDashboardTimewindow: true,
  datasources: [
    {
      type: 'entity',
      entityFilter: {
        type: 'deviceType',
        deviceTypes: ['peopleCount'], // ← all devices of this type
        deviceNameFilter: '',
        resolveMultiple: true,
      },
      dataKeys: [{ type: 'timeseries', name: 'peopleCount', settings: {} }],
    },
  ],
  callbacks: {
    onDataUpdated: (subscription) => render(subscription.data || []),
    onDataUpdateError: (subscription, e) => console.error(e),
  },
};
ctx.subscriptionApi.createSubscription(subOpts, true).subscribe();
